# Baker-Pixley / Bergman double projection: in a product of chains,
# R(X) = {x : every 2-coordinate projection of x lies in that projection of X}
import itertools
def E(X, d):
    proj = {}
    for i,j in itertools.combinations(range(d),2):
        proj[(i,j)] = {(x[i],x[j]) for x in X}
    alpha = [sorted({x[i] for x in X}) for i in range(d)]
    n = 0
    for pt in itertools.product(*alpha):
        if all((pt[i],pt[j]) in proj[(i,j)] for i,j in proj): n += 1
    return n - len(X), n, len(alpha[0])*len(alpha[1])*len(alpha[2])

# row 3 of the INDICES table: all 118 elements, charge 1..Z-1, ell 0..7
X = [(Z,c,l) for Z in range(1,119) for c in range(1,Z) for l in range(8)]
print("cells:", f"{len(X):,}")
e, closed, prod = E(X,3)
print("product:", f"{prod:,}", " |R(X)|:", f"{closed:,}", " E:", f"{e:,}")
EOF

