import collections, re
S=[l.rstrip("\r\n").split("\t") for l in open("captures/NEUTRALS-STAGING.tsv",encoding="utf-8") if l.strip()][1:]
C=[l.rstrip("\r\n").split("\t") for l in open("COORDINATES.tsv",encoding="utf-8") if l.strip()][1:]
wit={(r[0],r[1],r[2],r[3]) for r in C if len(r)>8 and r[8]=="witnessed"}
AB=[r for r in S if r[10] in ("A","B")]
k=collections.defaultdict(list)
for r in AB: k[(r[0],r[2],r[3])].append(r)
gap={key for key,v in k.items() if len(v)==1 and (key[0],"1",key[1],key[2]) not in wit}
zero={key for key in k if key[2]=="0"}
print("solo-unwritten keys:", len(gap), " mult=0 keys among A/B:", len(zero))
print("intersection:", len(gap & zero))
print("solo-unwritten with mult != 0:", len(gap - zero))
for key in sorted(gap-zero)[:8]:
    print("   ", key, k[key][0][6][:60])
print()
# check the tier/spread relation on single-member rows
def nr(s):
    m=re.search(r"n=(\d+)-(\d+)",s); return (int(m.group(1)),int(m.group(2))) if m else None
sing=[r for r in S if (x:=nr(r[6])) and x[0]==x[1]]
print("single-member rows by (tier, B-column):")
for t in ("A","B","C"):
    vals={r[7] for r in sing if r[10]==t}
    print(f"   tier {t}: n={sum(1 for r in sing if r[10]==t)}  distinct B values: {sorted(vals)[:5]}")
EOF

